// Shared subscribe-form wiring for index.html's landing form and every
// per-service page's pre-tagged form (site/s/<slug>.html, generated by
// site/build.py). A form opts in just by having class="signup-form"; an
// optional data-source attribute overrides the default source tag "site",
// and checked `input[name="tracks"]` boxes (if any) become tracks[] on the
// request body -- the main landing form ships with all five checked.
(function () {
  var API_BASE = window.TOS_WATCH_API_BASE || "";

  function wireForm(form) {
    var note = form.nextElementSibling;
    if (!note || !note.classList || !note.classList.contains("form-note")) note = null;

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var emailInput = form.querySelector('input[type="email"]');
      var email = emailInput ? emailInput.value.trim() : "";
      if (!email) return;

      var body = { email: email, source: form.dataset.source || "site" };
      var trackInputs = form.querySelectorAll('input[name="tracks"]');
      if (trackInputs.length) {
        body.tracks = Array.prototype.filter
          .call(trackInputs, function (c) { return c.checked; })
          .map(function (c) { return c.value; });
      } else if (form.dataset.tracks) {
        body.tracks = form.dataset.tracks.split(",").filter(Boolean);
      }

      var button = form.querySelector('button[type="submit"]');
      if (button) { button.disabled = true; button.textContent = "Subscribing…"; }

      function fail(message) {
        if (button) { button.disabled = false; button.textContent = "Subscribe"; }
        if (note) { note.textContent = message; note.classList.add("is-error"); note.setAttribute("role", "alert"); }
      }

      fetch(API_BASE + "/subscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      })
        .then(function (res) { return res.json().catch(function () { return {}; }); })
        .then(function (data) {
          if (data && data.ok) {
            showDone(form, note, email, data.next);
          } else if (data && data.error === "blocked") {
            fail("Our spam filter stopped this signup. Email hello@tos.watch and we'll add you by hand.");
          } else if (data && data.error === "rate_limited") {
            fail("Too many tries. Wait a minute and try again.");
          } else {
            fail("That didn't work. Check the email address and try again.");
          }
        })
        .catch(function () {
          fail("That didn't work. Check your connection and try again.");
        });
    });
  }

  // Replace the form with next steps, so it's obvious the signup went through.
  function showDone(form, note, email, next) {
    var panel = document.createElement("div");
    panel.className = "signup-done";
    panel.setAttribute("role", "status");
    panel.tabIndex = -1;

    var title = document.createElement("p");
    title.className = "signup-done-title";
    var detail = document.createElement("p");
    if (next === "saved") {
      title.textContent = "You're on the list.";
      detail.textContent = "We couldn't send the confirmation email just now. We'll send it to " + email + " shortly.";
    } else {
      title.textContent = "Check your inbox to finish.";
      detail.textContent = "We sent a confirmation link to " + email +
        ". Click it and you're subscribed. Nothing after a few minutes? Look in spam or Promotions.";
    }
    panel.appendChild(title);
    panel.appendChild(detail);

    form.replaceWith(panel);
    if (note) note.remove();
    panel.focus();
  }

  Array.prototype.forEach.call(document.querySelectorAll(".signup-form"), wireForm);
})();
